parameters.jsCode:
const items = $('Parse and Split Action Items').all();
const meetingTitle = items[0] ? items[0].json.meeting_title : 'Meeting';
const meetingDate = items[0] ? items[0].json.meeting_date : '';

const lines = items.map(function(item, i) {
  const icon = item.json.priority === 'High' ? '🔴' : item.json.priority === 'Medium' ? '🟡' : '🟢';
  return (i + 1) + '. ' + icon + ' *' + item.json.task_title + '*\n   → ' + item.json.assignee + ' | Due: ' + item.json.deadline;
});

return [{
  json: {
    slack_message: '📋 *Meeting Recap: ' + meetingTitle + '*\nDate: ' + meetingDate + '\n\n*' + items.length + ' action items added to Monday.com:*\n\n' + lines.join('\n\n') + '\n\n_Automated by n8n · tasks are live in Monday.com_',
    task_count: items.length,
    meeting_title: meetingTitle
  }
}];
